const upsertDiscoveredArtifactNode = `-- name: UpsertDiscoveredArtifactNode :exec
INSERT INTO foghorn.artifact_nodes
    (artifact_hash, node_id, file_path, size_bytes, last_seen_at, is_orphaned, cached_at)
VALUES ($1, $2, $3, $4, NOW(), false, NOW())
ON CONFLICT (artifact_hash, node_id) DO UPDATE SET
    file_path = EXCLUDED.file_path,
    size_bytes = EXCLUDED.size_bytes,
    last_seen_at = NOW(),
    is_orphaned = false
`

type UpsertDiscoveredArtifactNodeParams struct {
	ArtifactHash string         `db:"artifact_hash" json:"artifact_hash"`
	NodeID       string         `db:"node_id" json:"node_id"`
	FilePath     sql.NullString `db:"file_path" json:"file_path"`
	SizeBytes    sql.NullInt64  `db:"size_bytes" json:"size_bytes"`
}

func (q *Queries) UpsertDiscoveredArtifactNode(ctx context.Context, arg UpsertDiscoveredArtifactNodeParams) error {
	_, err := q.db.ExecContext(ctx, upsertDiscoveredArtifactNode,
		arg.ArtifactHash,
		arg.NodeID,
		arg.FilePath,
		arg.SizeBytes,
	)
	return err
}
